    const body=box('map-grid',parent),left=box('',body),right=box('map-ranking',body);
    const canvas=box('map-canvas svg-map',left),ranking=box('',right),unknown=box('',right);
    const clear=h('button','清除地区筛选',left),regionInfo=box('',parent),barArea=box('',parent);
    const geo=await load('provinces.json'),features=geo.features;
    const names=features.filter(f=>f.properties.name).map(f=>f.properties.name);
    if(new Set(names).size!==34){empty('省级地图数据不完整，请检查发布数据。',canvas);return}
    const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),layer=document.createElementNS(ns,'g');
    svg.setAttribute('viewBox','0 0 1000 650');svg.setAttribute('role','img');svg.setAttribute('aria-label','中国省级样本分布，可滚轮缩放和拖动');
    svg.append(layer);canvas.append(svg);const tooltip=box('map-tooltip',canvas);tooltip.hidden=true;
    let selected=p.get('region')||'',zoom=1,tx=0,ty=0,drag=null,moved=false;
    const points=[];function collect(coords){if(typeof coords[0]==='number')points.push(coords);else for(const c of coords)collect(c)}
    for(const f of features)collect(f.geometry.coordinates);
    const minX=Math.min(...points.map(p=>p[0])),maxX=Math.max(...points.map(p=>p[0]));
    const minY=Math.min(...points.map(p=>p[1])),maxY=Math.max(...points.map(p=>p[1]));
    const scale=Math.min(920/(maxX-minX),590/(maxY-minY)),padX=(1000-(maxX-minX)*scale)/2;
    function ring(coords){return coords.map((p,i)=>(i?'L':'M')+(padX+(p[0]-minX)*scale).toFixed(2)+','+(30+(maxY-p[1])*scale).toFixed(2)).join('')+'Z'}
